s printed, leave null: the writer uses verified retained confirmation/receipt Email receivedAt as the fallback and records provenance on Purchase.date. Preserve an explicit member date override. Shipping, delivery, cancellation and refund event timestamps are not order-date fallbacks. Null when no eligible date exists.\"},\"merchant\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":300},{\"type\":\"null\"}]},\"currency\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":3,\"maxLength\":3},{\"type\":\"null\"}]},\"printedGrandTotal\":{\"type\":[\"number\",\"null\"]},\"lines\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"title\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":500},\"amount\":{\"description\":\"The line's printed amount. Null only when the source prints the item without a price, under the `unpriced_itemization` review reason; never zero for an unknown price.\",\"type\":[\"number\",\"null\"]},\"lineKind\":{\"anyOf\":[{\"type\":\"string\",\"enum\":[\"unclassified\",\"principal\",\"tax\",\"shipping\",\"discount\",\"fee\",\"tip\",\"other_adjustment\"]},{\"type\":\"null\"}]},\"costType\":{\"anyOf\":[{\"type\":\"string\",\"enum\":[\"materials\",\"tools\",\"services\"]},{\"type\":\"null\"}],\"description\":\"The line's accounting role: materials for consumed or installed goods, tools for equipment that outlives the job, services for labor, travel, delivery, taxes, fees, and other non-material charges. Event tickets, airfare and other travel, lodging, rides, labor and prepared food are services.\"},\"quantity\":{\"anyOf\":[{\"type\":\"number\",\"exclusiveMinimum\":0},{\"type\":\"null\"}]},\"productUrl\":{\"anyOf\":[{\"type\":\"string\",\"format\":\"uri\"},{\"type\":\"null\"}]},\"imageUrl\":{\"anyOf\":[{\"type\":\"string\",\"format\":\"uri\"},{\"type\":\"null\"}]},\"sku\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":200},{\"type\":\"null\"}]},\"seller\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":300},{\"type\":\"null\"}]}},\"required\":[\"title\",\"amount\",\"lineKind\",\"costType\",\"quantity\",\"productUrl\",\"imageUrl\",\"sku\",\"seller\"],\"additionalProperties\":false}},\"payments\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"amount\":{\"type\":\"number\"},\"chargedAt\":{\"anyOf\":[{\"type\":\"string\",\"format\":\"date-time\",\"pattern\":\"^(?:(?:\\\\d\\\\d[2468][048]|\\\\d\\\\d[13579][26]|\\\\d\\\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\\\d|30)|(?:02)-(?:0[1-9]|1\\\\d|2[0-8])))T(?:(?:[01]\\\\d|2[0-3]):[0-5]\\\\d:[0-5]\\\\d(?:\\\\.\\\\d+)?(?:Z))$\"},{\"type\":\"null\"}]},\"cardLastFour\":{\"anyOf\":[{\"type\":\"string\",\"pattern\":\"^\\\\d{4}$\"},{\"type\":\"null\"}]},\"tender\":{\"anyOf\":[{\"type\":\"string\",\"enum\":[\"card\",\"stored_value\",\"unknown\"],\"description\":\"What paid this line: `card` (a card number, with cardLastFour when shown), `stored_value` (gift card, account balance or store credit), or `unknown`. A gift-card line is `stored_value`, never a card with no digits.\"},{\"type\":\"null\"}]},\"description\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":500},{\"type\":\"null\"}]}},\"required\":[\"amount\",\"chargedAt\",\"cardLastFour\",\"tender\",\"description\"],\"additionalProperties\":false}},\"shipments\":{\"maxItems\":50,\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"carrierClaims\":{\"description\":\"Package-specific carrier or intermediary claims. Copy an exact retained source statement/label containing the reference and literal carrier name. A constructed URL or format guess is inference, never proof. Preserve service wording; do not call merchants or brokers carriers.\",\"maxItems\":30,\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"trackingNumber\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":300},\"carrierName\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":300},\"role\":{\"type\":\"string\",\"enum\":[\"carrier\",\"intermediary\"]},\"service\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":300},{\"type\":\"null\"}]},\"evidence\":{\"anyOf\":[{\"type\":\"object\",\"properties\":{\"kind\":{\"type\":\"string\",\"const\":\"statement\"},\"quote\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1500}},\"required\":[\"kind\",\"quote\"],\"additionalProperties\":false},{\"type\":\"object\",\"properties\":{\"kind\":{\"type\":\"string\",\"const\":\"label\"},\"quote\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1500}},\"required\":[\"kind\",\"quote\"],\"additionalProperties\":false},{\"type\":\"object\",\"properties\":{\"kind\":{\"type\":\"string\",\"const\":\"link\"},\"href\":{\"type\":\"string\",\"maxLength\":2000,\"format\":\"uri\"}},\"required\":[\"kind\",\"href\"],\"additionalProperties\":false},{\"type\":\"object\",\"properties\":{\"kind\":{\"type\":\"string\",\"const\":\"inference\"}},\"required\":[\"kind\"],\"additionalProperties\":false}]}},\"required\":[\"trackingNumber\",\"carrierName\",\"role\",\"service\",\"evidence\"],\"additionalProperties\":false}},\"shipmentId\":{\"anyOf\":[{\"type\":\"string\",\"pattern\":\"^SHIP-[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{4,5}$\",\"description\":\"shipment shortcode, e.g. SHIP-4K7MN\"},{\"type\":\"null\"}]},\"sourceShipmentKey\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":500},{\"type\":\"null\"}],\"description\":\"Stable package identifier within this source; not a global Shipment identity. Repeated lifecycle Emails may identify the same package.\"},\"distinctPackageEvidence\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":2000},{\"type\":\"null\"}],\"description\":\"Retained evidence identifying a trackingless package, which also needs a stable sourceShipmentKey. This text never bypasses tracking identity matching. Separate packages sharing a tracking reference require member review.\"},\"carrierId\":{\"anyOf\":[{\"type\":\"string\",\"pattern\":\"^VEN-[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{4,5}$\",\"description\":\"vendor shortcode, e.g. VEN-4K7MN\"},{\"type\":\"null\"}]},\"carrierName\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":300},{\"type\":\"null\"}]},\"trackingNumber\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":300},{\"type\":\"null\"}]},\"extraTrackingNumbers\":{\"maxItems\":20,\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"carrierId\":{\"anyOf\":[{\"type\":\"string\",\"pattern\":\"^VEN-[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{4,5}$\",\"description\":\"vendor shortcode, e.g. VEN-4K7MN\"},{\"type\":\"null\"}]},\"carrierName\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":300},{\"type\":\"null\"}]},\"trackingNumber\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":300}},\"required\":[\"carrierId\",\"carrierName\",\"trackingNumber\"],\"additionalProperties\":false}},\"purpose\":{\"type\":\"string\",\"enum\":[\"incoming\",\"outgoing\",\"unknown\"],\"description\":\"Incoming or outgoing relative to the household. Received carrier SMS implies incoming; eBay sales and purchased postage labels are outgoing. Replacement and return details remain in the evidence.\"},\"observations\":{\"minItems\":1,\"maxItems\":500,\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"sourceEventKey\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":500},{\"type\":\"null\"}]},\"kind\":{\"type\":\"string\",\"enum\":[\"label_created\",\"vendor_shipped\",\"carrier_possession\",\"in_transit\",\"out_for_delivery\",\"delivery_attempt\",\"delivered\",\"exception\",\"returned\",\"cancelled\",\"unknown\"]},\"time\":{\"anyOf\":[{\"type\":\"object\",\"properties\":{\"kind\":{\"type\":\"string\",\"const\":\"instant\"},\"value\":{\"type\":\"string\",\"format\":\"date-time\",\"pattern\":\"^(?:(?:\\\\d\\\\d[2468][048]|\\\\d\\\\d[13579][26]|\\\\d\\\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\\\d|30)|(?:02)-(?:0[1-9]|1\\\\d|2[0-8])))T(?:(?:[01]\\\\d|2[0-3]):[0-5]\\\\d:[0-5]\\\\d(?:\\\\.\\\\d+)?(?:Z|([+-](?:[01]\\\\d|2[0-3]):[0-5]\\\\d)))$\"}},\"required\":[\"kind\",\"value\"],\"additionalProperties\":false},{\"type\":\"object\",\"properties\":{\"kind\":{\"type\":\"string\",\"const\":\"date\"},\"value\":{\"type\":\"string\",\"pattern\":\"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\",\"mockValue\":\"2024-01-15\",\"description\":\"Calendar day as \\\"YYYY-MM-DD\\\"\"}},\"required\":[\"kind\",\"value\"],\"additionalProperties\":false},{\"type\":\"object\",\"properties\":{\"kind\":{\"type\":\"string\",\"const\":\"local\"},\"value\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":100},\"timezone\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":100},{\"type\":\"null\"}]}},\"required\":[\"kind\",\"value\",\"timezone\"],\"additionalProperties\":false},{\"type\":\"object\",\"properties\":{\"kind\":{\"type\":\"string\",\"const\":\"unknown\"}},\"required\":[\"kind\"],\"additionalProperties\":false}],\"description\":\"Every new observation requires a date. Use its stated event time, otherwise the source notification date at date-only precision; estimates remain estimates.\"},\"timeBasis\":{\"type\":\"string\",\"enum\":[\"stated_event\",\"notification_received\",\"estimate\"],\"description\":\"stated_event for a completed event's stated date; notification_received when using the notification's date instead; estimate for forecast wording, which never proves completed delivery.\"},\"rawStatus\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":4000},\"location\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":500},{\"type\":\"null\"}]},\"carrierId\":{\"anyOf\":[{\"type\":\"string\",\"pattern\":\"^VEN-[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{4,5}$\",\"description\":\"vendor shortcode, e.g. VEN-4K7MN\"},{\"type\":\"null\"}]},\"carrierName\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":300},{\"type\":\"null\"}]},\"trackingNumber\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":300},{\"type\":\"null\"}]}},\"required\":[\"sourceEventKey\",\"kind\",\"time\",\"timeBasis\",\"rawStatus\",\"location\",\"carrierId\",\"carrierName\",\"trackingNumber\"],\"additionalProperties\":false}}},\"required\":[\"shipmentId\",\"sourceShipmentKey\",\"distinctPackageEvidence\",\"carrierId\",\"carrierName\",\"trackingNumber\",\"extraTrackingNumbers\",\"purpose\",\"observations\"],\"additionalProperties\":false}}},\"required\":[\"orderId\",\"orderedAt\",\"merchant\",\"currency\",\"printedGrandTotal\",\"lines\",\"payments\",\"shipments\"],\"additionalProperties\":false},{\"type\":\"null\"}]},\"reason\":{\"anyOf\":[{\"type\":\"string\",\"enum\":[\"missing_currency\",\"sum_mismatch\",\"unpriced_itemization\",\"foreign_currency\",\"missing_total\",\"ambiguous_order\"]},{\"type\":\"null\"}]},\"detail\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":1,\"maxLength\":2000},{\"type\":\"null\"}]}},\"required\":[\"status\",\"candidate\",\"reason\",\"detail\"],\"additionalProperties\":false}"}},{"feature":"run-summary","promptVersion":"2026-11-11.1","policy":{"tier":"fast","outputRevision":"{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"type\":\"object\",\"properties\":{\"text\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1200}},\"required\":[\"text\"],\"additionalProperties\":false}"}}]$features$::jsonb)
 -- cutover:model-features:end
), work_inputs AS (
 SELECT s.*, f.feature executable_feature, f.policy, f.prompt_version executable_version,
 coalesce(s.legacy->'snapshot'->'modelInput',s.legacy->'snapshot'->'envelope'->'input',s.legacy->'snapshot'->'input') model_input
 FROM source_answers s LEFT JOIN model_features f ON f.feature=CASE WHEN s.feature IN ('field_suggest','field_suggestion','field-suggestion') THEN 'field-suggestion.choice' ELSE replace(s.feature,'_','-') END
 WHERE s.source_table='AiEvaluation' AND s.state='queued' AND NOT s.cancelled
), work_envelopes AS (
 SELECT id,jsonb_build_object('feature',executable_feature,'producer','model','tier',policy->'tier','model',policy->'model','parameters',policy->'parameters','outputRevision',policy->>'outputRevision','promptVersion',executable_version,'input',model_input) envelope
 FROM work_inputs WHERE executable_feature IS NOT NULL AND coalesce(legacy->'snapshot'->'envelope'->>'promptVersion',prompt_version)=executable_version
 AND jsonb_typeof(model_input)='object' AND jsonb_typeof(model_input->'model')='string'
 AND (model_input->>'kind'='choice' AND policy->>'tier'='decision'
   AND jsonb_typeof(model_input->'subject')='string' AND jsonb_typeof(model_input->'rules')='string'
   AND jsonb_typeof(model_input->'choices')='array' AND NOT jsonb_path_exists(model_input,'$.choices[*] ? (@.type() != "string")')
   AND jsonb_typeof(model_input->'allowNone')='boolean'
 OR model_input->>'kind'='structured' AND policy->>'tier'<>'decision'
   AND jsonb_typeof(model_input->'request'->'systemPrompts')='array' AND NOT jsonb_path_exists(model_input,'$.request.systemPrompts[*] ? (@.type() != "string")')
   AND jsonb_typeof(model_input->'request'->'messages')='array' AND NOT jsonb_path_exists(model_input,'$.request.messages[*] ? (@.role != "user" || !(exists(@.content)))')
   AND jsonb_typeof(model_input->'parameters'->'schema')='object' AND jsonb_typeof(model_input->'parameters'->'maxTokens')='number')
), envelope_nodes(id,path,value,prefix) AS (
 SELECT id,ARRAY[]::text[],envelope,''::text FROM work_envelopes
 UNION ALL
 SELECT n.id,n.path||child.part,child.value,child.prefix FROM envelope_nodes n
 CROSS JOIN LATERAL (
   SELECT '1'||key part,value,CASE WHEN row_number() OVER(ORDER BY key COLLATE "C")>1 THEN ',' ELSE '' END||to_jsonb(key)::text||':' prefix FROM jsonb_each(CASE WHEN jsonb_typeof(n.value)='object' THEN n.value ELSE '{}'::jsonb END)
   UNION ALL
   SELECT '1'||lpad(ord::text,20,'0'),value,CASE WHEN ord>1 THEN ',' ELSE '' END FROM jsonb_array_elements(CASE WHEN jsonb_typeof(n.value)='array' THEN n.value ELSE '[]'::jsonb END) WITH ORDINALITY a(value,ord)
 ) child
), envelope_hashes AS (
 SELECT id,encode(sha256(convert_to(string_agg(piece,'' ORDER BY path COLLATE "C"),'UTF8')),'hex') hash FROM (
 SELECT id,path||ARRAY['0'] path,prefix||CASE jsonb_typeof(value) WHEN 'object' THEN '{' WHEN 'array' THEN '[' WHEN 'number' THEN CASE WHEN position('.' IN value::text)>0 THEN rtrim(rtrim(value::text,'0'),'.') ELSE value::text END ELSE value::text END piece FROM envelope_nodes
 UNION ALL SELECT id,path||ARRAY['2'],CASE jsonb_typeof(value) WHEN 'object' THEN '}' ELSE ']' END FROM envelope_nodes WHERE jsonb_typeof(value) IN ('object','array')
 ) tokens GROUP BY id
), executable_work AS (
 SELECT e.id,e.envelope,h.hash FROM work_envelopes e JOIN envelope_hashes h USING(id)
), imports AS (
 SELECT s.*,coalesce(w.hash,'legacy:'||s.source_table||':'||s.id::text) hash,
 CASE WHEN s.source_table='Suggestion' AND (s.legacy->'producer'->>'kind'='rule' OR s.legacy->>'model'='rule') THEN 'source' ELSE 'model' END producer,
 w.envelope,CASE WHEN w.id IS NULL THEN s.id ELSE min(s.id::text) OVER(PARTITION BY w.hash)::uuid END ask_id,
 s.cancelled OR s.source_table='AiEvaluation' AND s.state='queued' AND w.id IS NULL cancel_import
 FROM source_answers s LEFT JOIN executable_work w ON w.id=s.id AND s.source_table='AiEvaluation'
), ask_rows AS (
 SELECT DISTINCT ON (ask_id) * FROM imports ORDER BY ask_id,id
), review_events AS (
 SELECT s.id, d.event, d.ord FROM "Suggestion" s CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(s.decisions)='array' THEN s.decisions ELSE '[]'::jsonb END) WITH ORDINALITY d(event,ord) WHERE s.family IN ('field','statement_transaction','recommendation')
 UNION ALL
 SELECT s.id,jsonb_build_object('verdict',CASE WHEN s.suppression IS NOT NULL THEN 'wrong' ELSE 'correct' END,
 'intent','apply','correction',CASE WHEN s."confirmedValue"->>'present'='true' THEN s."confirmedValue" ELSE jsonb_build_object('present',s."correctValue" IS NOT NULL,'value',s."correctValue") END,
 'authority',CASE WHEN s."acceptanceReceipt"->>'mode'='automatic' THEN 'automatic' ELSE 'unknown' END,
 'createdAt',coalesce(nullif(s."acceptanceReceipt"->>'acceptedAt',''),s."updatedAt"::text,s."createdAt"::text)),
 0::bigint FROM "Suggestion" s WHERE s.family IN ('field','statement_transaction','recommendation') AND jsonb_array_length(CASE WHEN jsonb_typeof(s.decisions)='array' THEN s.decisions ELSE '[]'::jsonb END)=0
 AND (s.suppression IS NOT NULL OR s."confirmedValue"->>'present'='true' OR s."acceptanceReceipt"->>'mode'='member')
), reviews AS (
 SELECT s.*, d.event, d.ord,
 CASE WHEN d.event->'correction'->>'present'='true' THEN d.event->'correction'->'value' ELSE s."suggestedValue" END accepted
 FROM "Suggestion" s JOIN review_events d ON d.id=s.id
 WHERE d.event->>'authority' IS DISTINCT FROM 'automatic'
), statement_applications AS (
 SELECT v.*,o.id occurrence_id,o."acceptedTransactionId" transaction_id
 FROM reviews v JOIN "SourceTransactionRecord" observation ON observation.id=v."recordId"
 JOIN "SourceOccurrence" o ON o.id=observation."occurrenceId"
 WHERE v.family='statement_transaction' AND v.event->>'authority'='member'
), connection_reviews AS (
 SELECT v.*, candidate.value candidate,
 coalesce((SELECT target FROM survivors WHERE id=src.id),src.id) source_id,
 coalesce((SELECT target FROM survivors WHERE id=dst.id),dst.id) target_id
 FROM reviews v CROSS JOIN LATERAL (SELECT coalesce(v.evidence->'candidate',v.data->'candidate')) candidate(value)
 LEFT JOIN "Entity" src ON src.kind=candidate.value->'source'->>'entityKind' AND (src.id::text=candidate.value->'source'->>'entityId' OR src.shortcode=candidate.value->'source'->>'entityId')
 LEFT JOIN "Entity" dst ON dst.kind=candidate.value->'target'->>'entityKind' AND (dst.id::text=candidate.value->'target'->>'entityId' OR dst.shortcode=candidate.value->'target'->>'entityId')
 WHERE v.family='recommendation'
), expected AS (
 SELECT 'recordKey'::text mapping, entity||':'||id source_id,
 jsonb_build_object('scopeKind',scope_kind,'scopeKey',scope_key,'entity',entity,'naturalKey','legacy:'||id,'entityId',coalesce((SELECT target FROM survivors WHERE survivors.id=records.id),id),'rejectedAt',CASE WHEN EXISTS(SELECT 1 FROM survivors WHERE survivors.id=records.id) THEN NULL ELSE payload->'deletedAt' END) row
 FROM records
 UNION ALL
 SELECT 'manualEntry',entity||':'||id,
 jsonb_build_object('id',md5('cutover:'||entity||':'||id||CASE WHEN scope_kind='bankEvent' THEN ':'||scope_key ELSE '' END)::uuid,'entity',entity,'userId','legacy:unknown',
 'payload',jsonb_build_object('table',table_name,'naturalKey','legacy:'||id,'values',CASE WHEN cardinality(fields)>0 THEN (SELECT jsonb_object_agg(f,payload->f) FROM unnest(fields) f) ELSE payload END,'legacy',payload,'acceptedScope',jsonb_build_object('kind',scope_kind,'key',scope_key)))
 FROM records
 UNION ALL
 SELECT 'binding',entity||':'||id,jsonb_build_object('factKind','manualEntry','factId',md5('cutover:'||entity||':'||id||CASE WHEN scope_kind='bankEvent' THEN ':'||scope_key ELSE '' END)::uuid,'basis','baseline','eventKey',CASE WHEN scope_kind='fields' THEN 'baseline:snapshot:'||entity||':'||id ELSE id::text END,'scopeKind',scope_kind,'scopeKey',scope_key) FROM records
 UNION ALL
 SELECT 'scope',scope_kind||':'||scope_key,jsonb_build_object('scopeKind',scope_kind,'scopeKey',scope_key,'version',0,'rules','','stage','done') FROM records GROUP BY scope_kind,scope_key
 UNION ALL
 SELECT 'scope','bankEvent:'||id,jsonb_build_object('scopeKind','bankEvent','scopeKey',id,'version',0,'rules','','stage','done') FROM "SourceOccurrence"
 UNION ALL
 SELECT 'scope','purchaseEvent:'||id,jsonb_build_object('scopeKind','purchaseEvent','scopeKey',id,'version',0,'rules','','stage','done') FROM "FinancialTransaction"
 UNION ALL
 SELECT 'scope','connections:'||"scopeKey",jsonb_build_object('scopeKind','connections','scopeKey',"scopeKey",'version',0,'rules','','stage','done') FROM "ConnectionCandidateEvidence" GROUP BY "scopeKey"
 UNION ALL
 SELECT 'decision',entity||':'||id||':'||field,jsonb_build_object('id',('ffffffff'||substr(md5('cutover-held:'||entity||':'||id||':'||field),9))::uuid,
 'channel','assignment','subject',entity||':'||id,'slot',field,'field',field,'kind',CASE WHEN value='null'::jsonb THEN 'none' ELSE 'set' END,'value',value,
 'actorKind',CASE WHEN audit_id IS NULL OR authority IS NOT NULL OR audit_value IS DISTINCT FROM value OR channel='system' OR "userId"='cubby-system' THEN 'system' WHEN "oauthClientId" IS NOT NULL THEN 'agent' ELSE 'member' END,
 'actorId',CASE WHEN authority IS NULL AND audit_value=value THEN "userId" END,'at',now() AT TIME ZONE 'UTC')
 FROM field_values WHERE cubby_holds IS NOT TRUE
 UNION ALL
 SELECT 'answer',entity||':'||id||':'||field,jsonb_build_object('inputHash','legacy:field:'||entity||':'||id||':'||field,'feature','legacy:field','producer','model','promptVersion','legacy:unknown',
 'output',jsonb_build_object('value',value,'auditId',audit_id,'subject',entity||':'||id,'field',field),'createdAt',audit_at) FROM field_values WHERE cubby_holds
 UNION ALL
 SELECT 'ask',i.source_table||':'||i.id,jsonb_build_object('id',c.ask_id,'inputHash',c.hash,'feature',coalesce(c.envelope->>'feature','legacy:'||c.feature),'producer',c.producer,'promptVersion',coalesce(c.envelope->>'promptVersion',c.prompt_version),
 'input',coalesce(c.envelope,jsonb_build_object('legacy',c.legacy,'sourceTable',c.source_table)),'state',c.state,'cancelledAt',CASE WHEN c.cancel_import THEN coalesce(c.legacy->'updatedAt',to_jsonb(now() AT TIME ZONE 'UTC')) END,
 'availableAt',c.available_at,'attempts',c.attempts,'maxAttempts',greatest(3,c.attempts+1),'lastError',CASE WHEN c.cancel_import AND NOT c.cancelled THEN 'Cutover cancelled legacy queued work: incomplete canonical input or unregistered feature' ELSE c.error END,'waitCause',CASE WHEN c.legacy->>'waitCause' IN ('funding','provider_capacity','in_flight','rate_limit','device') THEN c.legacy->>'waitCause' END,'createdAt',c.created_at,'executor',CASE WHEN c.envelope IS NULL THEN 'legacy' END) FROM imports i JOIN ask_rows c USING(ask_id)
 UNION ALL
 SELECT 'answer',source_table||':'||id,jsonb_build_object('inputHash',hash,'feature','legacy:'||feature,'producer',producer,'promptVersion',prompt_version,
 'output',jsonb_build_object('result',result,'legacy',legacy,'sourceTable',source_table),'model',model,'askId',ask_id,'runId',run_id,'createdAt',created_at) FROM imports WHERE result IS NOT NULL
 UNION ALL
 SELECT 'askScope',source_table||':'||id||':owner',jsonb_build_object('askId',ask_id,'scopeKind','run','scopeKey',run_id,'runId',run_id,'receipt',legacy->'receipt','createdAt',created_at) FROM imports WHERE run_id IS NOT NULL
 UNION ALL
 SELECT 'askScope',source_table||':'||id||':record',jsonb_build_object('askId',ask_id,'scopeKind',CASE WHEN target->>'entity' IN ('product','cookbook','location','meal','project','task','vendor','financialAccount','planting','gardenEntry','productCategory','run','device','spendingCategory') THEN 'fields' ELSE 'record' END,
 'scopeKey',(target->>'entity')||':'||(target->>'recordId'),'createdAt',created_at) FROM imports WHERE target->>'recordId' IS NOT NULL
 UNION ALL
 SELECT 'askScope','AiEvaluationRequest:'||r.id,jsonb_build_object('askId',i.ask_id,'scopeKind','run','scopeKey',r."runId",'runId',r."runId",'receipt',r.receipt,'sequence',r.sequence,'cancelledAt',r."cancelledAt",'createdAt',r."createdAt") FROM "AiEvaluationRequest" r JOIN imports i ON i.source_table='AiEvaluation' AND i.id=r."evaluationId"
 UNION ALL
 SELECT 'decision','Suggestion:'||id||':'||ord,jsonb_build_object('id',md5('cutover-review:'||id||':'||ord)::uuid,'channel',CASE WHEN event->>'verdict' IN ('wrong','dismissed') THEN 'veto' ELSE 'assignment' END,
 'subject',entity||':'||"recordId",'slot',CASE WHEN event->>'verdict' IN ('wrong','dismissed') THEN field||chr(31)||encode(sha256(convert_to("suggestedValue"::text,'UTF8')),'hex') ELSE field END,'field',field,'kind',CASE WHEN event->>'verdict' IN ('wrong','dismissed') THEN 'veto' WHEN accepted='null'::jsonb THEN 'none' ELSE 'set' END,
 'value',CASE WHEN event->>'verdict' IN ('wrong','dismissed') THEN "suggestedValue" ELSE accepted END,'actorKind',CASE WHEN event->>'authority'='member' THEN 'member' ELSE 'system' END,'actorId',event->>'actorUserId','at',(event->>'createdAt')::timestamp)
 FROM reviews WHERE family='field' AND field<>'' AND "recordId" IS NOT NULL AND event->>'verdict' IN ('correct','wrong','dismissed') AND (event->>'verdict'<>'correct' OR event->>'intent'='apply' AND EXISTS (SELECT 1 FROM field_values f WHERE f.entity=reviews.entity AND f.id=reviews."recordId" AND f.field=reviews.field AND f.cubby_holds IS NOT TRUE AND f.value IS NOT DISTINCT FROM reviews.accepted))
UNION ALL
SELECT 'decision','Suggestion:'||r.id,jsonb_build_object('id',md5('cutover:Suggestion:'||r.id)::uuid,'channel','assignment','subject','legacy:suggestion:'||r.id,'slot','review','field','review','kind','set','value',to_jsonb(r),'actorKind','system','actorId',NULL,'at',r."updatedAt") FROM "Suggestion" r WHERE r.family IN ('field','statement_transaction','recommendation') AND r.field='' AND (jsonb_array_length(r.decisions)>0 OR r.suppression IS NOT NULL OR r."confirmedValue" IS NOT NULL)
UNION ALL
SELECT 'decision','Connection:'||id||':'||ord,jsonb_build_object('id',md5('cutover:connection:'||id||':'||ord)::uuid,
 'channel','assignment','subject','connection/'||(candidate->>'relation')||':'||source_id||':'||target_id,'slot','link','field','link','kind','set',
 'value',event->>'verdict'='correct','actorKind',CASE WHEN event->>'authority'='member' THEN 'member' ELSE 'system' END,'actorId',event->>'actorUserId','at',(event->>'createdAt')::timestamp)
FROM connection_reviews WHERE source_id IS NOT NULL AND target_id IS NOT NULL AND candidate->>'relation' IS NOT NULL AND (event->>'verdict' IN ('wrong','dismissed') OR event->>'verdict'='correct' AND event->>'intent'='apply')
UNION ALL
SELECT 'decision','AuditLog:release:'||a.id||':'||f.key,jsonb_build_object('id',md5('cutover:release:'||a.id||':'||f.key)::uuid,'channel','assignment','subject',a."entityKind"||':'||a."entityId",'slot',f.key,'field',f.key,'kind','release','value',NULL,'actorKind',CASE WHEN a.channel='system' OR a."userId"='cubby-system' THEN 'system' WHEN a."oauthClientId" IS NULL THEN 'member' ELSE 'agent' END,'actorId',a."userId",'at',a."createdAt") FROM "AuditLog" a CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(a.changes)='object' THEN a.changes ELSE '{}'::jsonb END) f WHERE a.authority='released' AND EXISTS(SELECT 1 FROM field_values r WHERE r.entity=a."entityKind" AND r.id=a."entityId" AND r.field=f.key AND r.cubby_holds)

UNION ALL
SELECT 'decision','AuditLog:held:'||a.id||':'||f.key,jsonb_build_object('id',md5('cutover:audit-held:'||a.id||':'||f.key)::uuid,'channel','assignment','subject',a."entityKind"||':'||a."entityId",'slot',f.key,'field',f.key,'kind',CASE WHEN f.value->'to'='null'::jsonb THEN 'none' ELSE 'set' END,'value',CASE WHEN jsonb_typeof(f.value->'to')='number' THEN CASE
 WHEN ((a."entityKind"='financialTransaction' AND f.key='amount') OR (a."entityKind"='purchase' AND f.key='statedTotal') OR (a."entityKind"='expense' AND f.key='cost'))
  AND abs((f.value->'to' #>> '{}')::numeric*100-round((f.value->'to' #>> '{}')::numeric*100))<0.0000001 THEN to_jsonb(round((f.value->'to' #>> '{}')::numeric*100)::text)
 WHEN a."entityKind"='FinancialTransactionAllocation' AND f.key='amountMinor' AND (f.value->'to' #>> '{}')::numeric=trunc((f.value->'to' #>> '{}')::numeric) THEN to_jsonb(trunc((f.value->'to' #>> '{}')::numeric)::text)
 ELSE f.value->'to' END ELSE f.value->'to' END,'actorKind',CASE WHEN a.channel='system' OR a."userId"='cubby-system' THEN 'system' WHEN a."oauthClientId" IS NULL THEN 'member' ELSE 'agent' END,'actorId',a."userId",'at',a."createdAt") FROM "AuditLog" a CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(a.changes)='object' THEN a.changes ELSE '{}'::jsonb END) f WHERE a.authority IS NULL AND f.value ? 'to' AND EXISTS(SELECT 1 FROM field_values r WHERE r.entity=a."entityKind" AND r.id=a."entityId" AND r.field=f.key AND r.cubby_holds IS NOT TRUE AND r.value IS NOT DISTINCT FROM f.value->'to')

UNION ALL
SELECT 'decision','Suggestion:correction-veto:'||id||':'||ord,jsonb_build_object('id',md5('cutover:correction-veto:'||id||':'||ord)::uuid,
 'channel','veto','subject',entity||':'||"recordId",'slot',field||chr(31)||encode(sha256(convert_to("suggestedValue"::text,'UTF8')),'hex'),'field',field,'kind','veto','value',"suggestedValue",
 'actorKind',CASE WHEN event->>'authority'='member' THEN 'member' ELSE 'system' END,'actorId',event->>'actorUserId','at',(event->>'createdAt')::timestamp)
FROM reviews WHERE family='field' AND field<>'' AND "recordId" IS NOT NULL AND event->>'verdict'='correct' AND event->>'intent'='apply' AND event->'correction'->>'present'='true' AND accepted IS DISTINCT FROM "suggestedValue"
UNION ALL
SELECT 'decision','Suggestion:review:'||id||':'||ord,jsonb_build_object('id',md5('cutover:review-event:'||id||':'||ord)::uuid,
 'channel','assignment','subject','legacy:suggestion:'||id,'slot','review:'||ord,'field','review','kind','set','value',event,
 'actorKind',CASE WHEN event->>'authority'='member' THEN 'member' ELSE 'system' END,'actorId',event->>'actorUserId','at',(event->>'createdAt')::timestamp)
FROM reviews WHERE family<>'field' OR field=''

UNION ALL
SELECT 'decision','StatementApplication:'||id||':'||ord||':'||a.field,jsonb_build_object('id',md5('cutover:statement:'||id||':'||ord||':'||a.field)::uuid,
 'channel','assignment','subject','bank:'||occurrence_id,'slot',a.field,'field',a.field,'kind','set','value',a.value,'actorKind','member','actorId',event->>'actorUserId','at',(event->>'createdAt')::timestamp)
FROM statement_applications CROSS JOIN LATERAL (VALUES ('accountId',coalesce(accepted->'accountId',data->'accountId')),('kind',accepted->'kindOverride')) a(field,value)
WHERE event->>'intent'='apply' AND jsonb_typeof(a.value)='string'
UNION ALL
SELECT 'decision','StatementBooking:'||id||':'||ord||':'||b.key,jsonb_build_object('id',md5('cutover:booking:'||id||':'||ord||':'||b.key)::uuid,
 'channel','assignment','subject','purchaseEvent:'||transaction_id,'slot',CASE WHEN b.key='reviewedVendorName' THEN 'vendorName' ELSE b.key END,'field',CASE WHEN b.key='reviewedVendorName' THEN 'vendorName' ELSE b.key END,
 'kind',CASE WHEN b.value='null'::jsonb THEN 'none' ELSE 'set' END,'value',b.value,'actorKind','member','actorId',event->>'actorUserId','at',(event->>'createdAt')::timestamp)
FROM statement_applications CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(accepted->'booking')='object' THEN accepted->'booking' ELSE '{}'::jsonb END) b
WHERE event->>'intent'='apply' AND transaction_id IS NOT NULL
UNION ALL
SELECT 'decision','StatementBook:'||id||':'||ord,jsonb_build_object('id',md5('cutover:book:'||id||':'||ord)::uuid,
 'channel','assignment','subject','purchaseEvent:'||transaction_id,'slot','book','field','book','kind','set','value',true,'actorKind','member','actorId',event->>'actorUserId','at',(event->>'createdAt')::timestamp)
FROM statement_applications WHERE event->>'intent'='apply' AND accepted->>'action'='book' AND transaction_id IS NOT NULL
UNION ALL
SELECT 'decision','StatementDistinct:'||a.id||':'||a.ord||':'||candidate.id,jsonb_build_object('id',md5('cutover:distinct:'||a.id||':'||a.ord||':'||candidate.id)::uuid,
 'channel','identity','subject','financialTransaction:'||least(a.transaction_id::text,candidate.id::text),'other','financialTransaction:'||greatest(a.transaction_id::text,candidate.id::text),
 'slot','financialTransaction:'||greatest(a.transaction_id::text,candidate.id::text),'field','financialTransaction:'||greatest(a.transaction_id::text,candidate.id::text),'kind','distinct','value',NULL,'actorKind','member','actorId',a.event->>'actorUserId','at',(a.event->>'createdAt')::timestamp)
FROM statement_applications a CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(a.accepted->'rejectedCandidateIds')='array' THEN a.accepted->'rejectedCandidateIds' ELSE '[]'::jsonb END) rejected(code)
JOIN "Entity" candidate ON candidate.kind='financialTransaction' AND (candidate.shortcode=rejected.code OR candidate.id::text=rejected.code)
WHERE a.event->>'intent'='apply' AND a.transaction_id IS NOT NULL AND candidate.id<>a.transaction_id
UNION ALL
SELECT 'decision','Rejected:'||entity||':'||id,jsonb_build_object('id',md5('cutover:rejected:'||entity||':'||id)::uuid,
 'channel','rejection','subject',entity||':'||id,'slot','','kind','reject','value',NULL,'actorKind','system','actorId',NULL,'at',payload->'deletedAt')
FROM records WHERE payload->>'deletedAt' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM survivors WHERE survivors.id=records.id)

UNION ALL
-- A current automatic/released trail supersedes old held assignments. This is
-- an observation of authority at cutover, not a fabricated member release.
SELECT 'decision','CubbyRelease:'||entity||':'||id||':'||field,jsonb_build_object('id',md5('cutover:cubby-release:'||entity||':'||id||':'||field)::uuid,
 'channel','assignment','subject',entity||':'||id,'slot',field,'field',field,'kind','release','value',NULL,'actorKind','system','actorId',NULL,'at',now() AT TIME ZONE 'UTC')
FROM field_values WHERE cubby_holds
), empty_scopes AS (
 SELECT DISTINCT e.row->>'scopeKind' kind,e.row->>'scopeKey' key FROM expected e WHERE e.mapping='scope'
 AND NOT EXISTS (SELECT 1 FROM expected k WHERE k.mapping='recordKey' AND k.row->>'scopeKind'=e.row->>'scopeKind' AND k.row->>'scopeKey'=e.row->>'scopeKey')
), complete_expected AS (
 SELECT mapping,source_id,row FROM expected
 UNION ALL
 SELECT 'manualEntry','emptyScope:'||kind||':'||key,jsonb_build_object('id',md5('cutover:empty:'||kind||':'||key)::uuid,'entity','scope','userId','legacy:unknown',
 'payload',jsonb_build_object('emptyBaseline',true,'acceptedScope',jsonb_build_object('kind',kind,'key',key))) FROM empty_scopes
 UNION ALL
 SELECT 'binding','emptyScope:'||kind||':'||key,jsonb_build_object('factKind','manualEntry','factId',md5('cutover:empty:'||kind||':'||key)::uuid,'basis','baseline','eventKey','baseline:empty:'||kind||':'||key,'scopeKind',kind,'scopeKey',key) FROM empty_scopes
)
SELECT mapping,source_id,row FROM complete_expected
-- cutover:select:end
;
