UPDATE "RecordKey" k SET "mergedAt"=coalesce(e."deletedAt",now() AT TIME ZONE 'UTC')
FROM "Entity" e WHERE k."naturalKey"='legacy:'||e.id AND e."mergedIntoId" IS NOT NULL;
